USE finsecure_db;
SET FOREIGN_KEY_CHECKS = 0;

-- ── Inline schema patches ─────────────────────────────────────────────────────
-- Compatible with MySQL 5.7+. Uses stored procedures to conditionally
-- add columns only when they don't already exist.

DROP PROCEDURE IF EXISTS finsecure_add_col;

DELIMITER $$

CREATE PROCEDURE finsecure_add_col(
    IN p_table  VARCHAR(64),
    IN p_column VARCHAR(64),
    IN p_ddl    TEXT
)
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME   = p_table
          AND COLUMN_NAME  = p_column
    ) THEN
        SET @sql = CONCAT('ALTER TABLE `', p_table, '` ADD COLUMN ', p_ddl);
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END$$

DELIMITER ;

-- 1. users.token_version
CALL finsecure_add_col('users', 'token_version', 'token_version INT NOT NULL DEFAULT 0');

-- 2. cards: 5 columns missing from original schema.sql
CALL finsecure_add_col('cards', 'prepaid_balance', 'prepaid_balance DECIMAL(12,2) NOT NULL DEFAULT 0.00');
CALL finsecure_add_col('cards', 'annual_fee',      'annual_fee INT NOT NULL DEFAULT 0');
CALL finsecure_add_col('cards', 'perks',           'perks VARCHAR(500) NULL');
CALL finsecure_add_col('cards', 'scheme',          "scheme VARCHAR(20) NOT NULL DEFAULT ''STANDARD''");
CALL finsecure_add_col('cards', 'variant',         "variant VARCHAR(20) NOT NULL DEFAULT ''REGULAR''");

DROP PROCEDURE IF EXISTS finsecure_add_col;

ALTER TABLE cards
    MODIFY COLUMN scheme VARCHAR(20) NOT NULL DEFAULT 'STANDARD',
    MODIFY COLUMN variant VARCHAR(20) NOT NULL DEFAULT 'REGULAR',
    MODIFY COLUMN annual_fee INT NOT NULL DEFAULT 0;

-- 3. kyc_documents: file_data blob
-- (migrate_kyc_file_storage.sql may have already added this; MODIFY is always safe)
ALTER TABLE kyc_documents
    MODIFY COLUMN file_path TEXT NULL;

ALTER TABLE kyc_documents
    MODIFY COLUMN status ENUM(
        'UPLOADED','UNDER_REVIEW','APPROVED','REJECTED','SUPERSEDED'
    ) NOT NULL DEFAULT 'UPLOADED';

-- file_data — use procedure approach too
DROP PROCEDURE IF EXISTS finsecure_add_blob;

DELIMITER $$

CREATE PROCEDURE finsecure_add_blob()
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME   = 'kyc_documents'
          AND COLUMN_NAME  = 'file_data'
    ) THEN
        ALTER TABLE kyc_documents ADD COLUMN file_data MEDIUMBLOB NULL;
    END IF;
END$$

DELIMITER ;

CALL finsecure_add_blob();
DROP PROCEDURE IF EXISTS finsecure_add_blob;

