-- ── Recreate triggers after seed ─────────────────────────────────────────────

DELIMITER $$

CREATE TRIGGER before_credit_card_insert
BEFORE INSERT ON cards
FOR EACH ROW
BEGIN
    DECLARE kyc_status_val VARCHAR(20);
    IF NEW.card_type = 'CREDIT' THEN
        SELECT c.kyc_status INTO kyc_status_val
        FROM customers c
        INNER JOIN accounts a ON a.customer_id = c.id
        WHERE a.id = NEW.account_id
        LIMIT 1;
        IF kyc_status_val != 'APPROVED' THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Credit card cannot be issued without approved KYC';
        END IF;
    END IF;
END$$

CREATE TRIGGER audit_large_transaction
AFTER INSERT ON transactions
FOR EACH ROW
BEGIN
    IF NEW.amount > 100000 THEN
        SELECT
            u.id, u.username, 'LARGE_TRANSACTION', 'TRANSACTION', NEW.reference_number,
            CONCAT('Amount: ', NEW.amount, ' Mode: ', NEW.mode),
            'SUCCESS', NOW(6)
        FROM accounts a
        INNER JOIN customers c ON c.id = a.customer_id
        INNER JOIN users u ON u.id = c.user_id
        WHERE a.id = NEW.account_id
        LIMIT 1;
    END IF;
END$$

DELIMITER ;

-- NOTE: This script restores the two triggers defined by schema.sql above.
-- If your local database has extra custom triggers named
-- trg_prevent_negative_balance, trg_account_status_change, or
-- trg_kyc_approved, this dev seed drops them so historical dummy data can load.
-- Those custom triggers are not defined in this repository, so back them up
-- before running this script if you need to preserve them.
